package com.ryu.forkliftdiagnostic.ui;
import android.app.Activity;import android.os.Bundle;import android.graphics.*;import android.view.*;import android.widget.LinearLayout;
public class EvidenceViewerActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);LinearLayout body=Ui.page(this,"회로/근거 뷰어");ZoomView z=new ZoomView();z.setContentDescription("zoom_pan_canvas");body.addView(z,new LinearLayout.LayoutParams(-1,900));}
class ZoomView extends View{Paint p=new Paint(1);float scale=1,tx=0,ty=0,lastX,lastY;ScaleGestureDetector sd;GestureDetector gd;ZoomView(){super(EvidenceViewerActivity.this);p.setStrokeWidth(5);sd=new ScaleGestureDetector(getContext(),new ScaleGestureDetector.SimpleOnScaleGestureListener(){public boolean onScale(ScaleGestureDetector d){scale=Math.max(1,Math.min(5,scale*d.getScaleFactor()));invalidate();return true;}});gd=new GestureDetector(getContext(),new GestureDetector.SimpleOnGestureListener(){public boolean onDoubleTap(android.view.MotionEvent e){scale=scale>1?1:2.5f;if(scale==1){tx=0;ty=0;}invalidate();return true;}});}protected void onDraw(Canvas c){super.onDraw(c);c.save();c.translate(tx,ty);c.scale(scale,scale);p.setColor(Color.DKGRAY);p.setTextSize(34);c.drawText("LAMP 공통전원 → 분기 → 번호판등 B+",35,90,p);c.drawLine(60,150,760,150,p);p.setColor(Color.rgb(17,117,214));c.drawRect(90,210,320,340,p);c.drawRect(500,210,730,340,p);p.setColor(Color.WHITE);p.setTextSize(28);c.drawText("+전원 측정",120,285,p);c.drawText("접지 강하",535,285,p);c.restore();p.setColor(Color.BLACK);p.setTextSize(25);c.drawText("scale "+String.format(java.util.Locale.US,"%.2f",scale)+" · pinch / pan / double tap",20,getHeight()-25,p);}public boolean onTouchEvent(android.view.MotionEvent e){sd.onTouchEvent(e);gd.onTouchEvent(e);if(e.getPointerCount()==1&&!sd.isInProgress()){if(e.getAction()==0){lastX=e.getX();lastY=e.getY();}else if(e.getAction()==2&&scale>1){tx+=e.getX()-lastX;ty+=e.getY()-lastY;lastX=e.getX();lastY=e.getY();invalidate();}}return true;}}
}
